<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { opcApi } from '@/api/opc'

type Order={id:string;quote_id:string;customer:string;customer_id?:string;factory:string;factory_id?:string;product:string;amount:number;currency:string;due:string;progress:number;stage:string;payment:string;quality:string;logistics:string;exception:string}
const useMock=import.meta.env.VITE_USE_MOCK==='true';const search=ref('');const stageFilter=ref('');const dialog=ref(false);const detailDialog=ref(false);const editingId=ref('');const selected=ref<Order|null>(null)
const customerOptions=ref([{id:'c1',name:'河北安筑工程'},{id:'c2',name:'Green Farm LLC'},{id:'c3',name:'Nordic Fence AB'}]);const factoryOptions=ref([{id:'f1',name:'安平恒泰丝网厂'},{id:'f2',name:'安平华辰护栏厂'},{id:'f3',name:'河北鑫源金属网业'}])
const stages=['待排产','生产中','待质检','待装柜','运输中','已交付']
const stageProgress:Record<string,number>={'待排产':10,'生产中':35,'待质检':65,'待装柜':80,'运输中':92,'已交付':100}
const paymentCodes:Record<string,string>={'定金待收':'DEPOSIT_PENDING','定金已收':'DEPOSIT_PAID','尾款待收':'BALANCE_PENDING','已收全款':'PAID'}
const paymentLabels:Record<string,string>={DEPOSIT_PENDING:'定金待收',DEPOSIT_PAID:'定金已收',BALANCE_PENDING:'尾款待收',PAID:'已收全款'}
const orders=ref<Order[]>([
  {id:'ORD-20250922-012',quote_id:'QT-20250922-006',customer:'河北安筑工程',customer_id:'c1',factory:'安平恒泰丝网厂',factory_id:'f1',product:'建筑防护网',amount:58600,currency:'CNY',due:'2025-10-07',progress:35,stage:'生产中',payment:'定金已收',quality:'PENDING',logistics:'',exception:''},
  {id:'ORD-20250918-009',quote_id:'QT-20250918-011',customer:'Green Farm LLC',customer_id:'c2',factory:'安平华辰护栏厂',factory_id:'f2',product:'六角网',amount:8920,currency:'USD',due:'2025-09-28',progress:65,stage:'待质检',payment:'定金已收',quality:'WAITING_PHOTOS',logistics:'',exception:'等待上传质检照片'},
  {id:'ORD-20250912-006',quote_id:'QT-20250922-005',customer:'Nordic Fence AB',customer_id:'c3',factory:'河北鑫源金属网业',factory_id:'f3',product:'养殖围网',amount:12840,currency:'USD',due:'2025-09-24',progress:80,stage:'待装柜',payment:'尾款待收',quality:'PASSED',logistics:'订舱完成',exception:'尾款到账后放货'},
])
const form=reactive({quote_id:'',customer:'',customer_id:'',factory:'',factory_id:'',product:'',amount:0,currency:'CNY',due:'',stage:'待排产',payment:'定金待收',quality:'PENDING',logistics:'',exception:''})
const filtered=computed(()=>orders.value.filter(x=>(!search.value||`${x.id}${x.customer}${x.factory}${x.product}`.toLowerCase().includes(search.value.toLowerCase()))&&(!stageFilter.value||x.stage===stageFilter.value)))
const amountText=(x:Order)=>`${x.currency==='CNY'?'¥':'$'}${x.amount.toLocaleString()}`
onMounted(async()=>{if(useMock)return;try{const[orderRes,customerRes,factoryRes]=await Promise.all([opcApi.listOrders(),opcApi.listCustomers(),opcApi.listFactories()]);customerOptions.value=customerRes.data.map((x:any)=>({id:x.id,name:x.name}));factoryOptions.value=factoryRes.data.map((x:any)=>({id:x.id,name:x.name}));orders.value=orderRes.data.map((x:any)=>({id:x.id,quote_id:x.quote_id,customer:customerOptions.value.find(c=>c.id===x.customer_id)?.name||'未关联客户',customer_id:x.customer_id,factory:factoryOptions.value.find(f=>f.id===x.factory_id)?.name||'未分配工厂',factory_id:x.factory_id,product:'丝网产品',amount:x.amount,currency:x.currency,due:x.due_date?.slice(0,10)||'',progress:stageProgress[x.status]||10,stage:x.status,payment:paymentLabels[x.payment_status]||'待确认',quality:x.quality_status,logistics:JSON.stringify(x.logistics||{}),exception:''}))}catch{ElMessage.warning('订单数据加载失败，已保留演示数据')}})
function reset(){Object.assign(form,{quote_id:'',customer:'',customer_id:'',factory:'',factory_id:'',product:'',amount:0,currency:'CNY',due:'',stage:'待排产',payment:'定金待收',quality:'PENDING',logistics:'',exception:''})}
function openCreate(){editingId.value='';reset();dialog.value=true}
function openEdit(x:Order){editingId.value=x.id;Object.assign(form,x);dialog.value=true}
function openDetail(x:Order){selected.value=x;detailDialog.value=true}
async function save(){form.customer=customerOptions.value.find(x=>x.id===form.customer_id)?.name||'';form.factory=factoryOptions.value.find(x=>x.id===form.factory_id)?.name||'';if(!form.quote_id||!form.customer_id||!form.factory_id)return ElMessage.warning('请填写报价编号、客户和合作工厂');const payload={quote_id:form.quote_id,customer_id:form.customer_id,factory_id:form.factory_id,status:form.stage,amount:form.amount,currency:form.currency,due_date:form.due?`${form.due}T00:00:00`:null,quality_status:form.quality,payment_status:paymentCodes[form.payment]||'DEPOSIT_PENDING',contract_no:'',invoice_status:'NOT_REQUESTED',logistics:{text:form.logistics,exception:form.exception}};if(editingId.value){if(!useMock)await opcApi.updateOrder(editingId.value,payload);const x=orders.value.find(x=>x.id===editingId.value);if(x)Object.assign(x,form,{progress:stageProgress[form.stage]})}else{const id=useMock?`ORD-${Date.now()}`:(await opcApi.createOrder(payload)).data.id;orders.value.unshift({id,...form,progress:stageProgress[form.stage]})}dialog.value=false;ElMessage.success('订单已保存')}
async function remove(x:Order){await ElMessageBox.confirm(`确认删除订单 ${x.id}？`,'删除订单',{type:'warning'});if(!useMock)await opcApi.deleteOrder(x.id);orders.value=orders.value.filter(i=>i.id!==x.id);ElMessage.success('订单已删除')}
async function advance(x:Order){const index=stages.indexOf(x.stage);if(index>=stages.length-1)return ElMessage.info('订单已完成交付');const next=stages[index+1];if(!useMock)await opcApi.createOrderEvent(x.id,{event_type:'status_changed',to_status:next,data:{source:'web'}});x.stage=next;x.progress=stageProgress[x.stage];if(x.stage==='待质检')x.quality='WAITING_PHOTOS';if(x.stage==='运输中')x.logistics='等待录入运单';if(x.stage==='已交付')x.payment='已收全款';ElMessage.success(`订单已推进至：${x.stage}`)}
async function setQuality(x:Order,status:string){if(!useMock)await opcApi.createOrderEvent(x.id,{event_type:status==='PASSED'?'quality_passed':'quality_failed',data:{source:'web'}});x.quality=status;ElMessage.success(status==='PASSED'?'质检已通过':'已记录质检异常')}
defineExpose({openCreate})
</script>

<template><div>
  <div class="stats"><article><span>执行中订单</span><strong>{{ orders.filter(x=>x.stage!=='已交付').length }}</strong><em>当前生产负荷正常</em></article><article><span>订单总金额</span><strong>¥ {{ orders.filter(x=>x.currency==='CNY').reduce((s,x)=>s+x.amount,0).toLocaleString() }}</strong><em>另有 {{ orders.filter(x=>x.currency==='USD').length }} 笔外币订单</em></article><article><span>待质检/装柜</span><strong>{{ orders.filter(x=>['待质检','待装柜'].includes(x.stage)).length }}</strong><em>需重点跟进</em></article><article><span>交付异常</span><strong class="danger">{{ orders.filter(x=>x.exception).length }}</strong><em>待处理</em></article></div>
  <section class="card"><header><h3>订单执行看板</h3><div><el-input v-model="search" placeholder="搜索订单、客户或工厂" :prefix-icon="'Search'" clearable/><el-select v-model="stageFilter" placeholder="全部阶段" clearable><el-option v-for="s in stages" :key="s" :label="s" :value="s"/></el-select><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>新建订单</el-button></div></header><div class="table"><div class="row head"><span>订单/产品</span><span>客户/工厂</span><span>金额</span><span>交付日期</span><span>执行进度</span><span>收款</span><span>操作</span></div><div v-for="x in filtered" :key="x.id" class="row"><div><b class="order-id">{{ x.id }}</b><small>{{ x.product }}</small></div><div><b>{{ x.customer }}</b><small>{{ x.factory }}</small></div><strong>{{ amountText(x) }}</strong><span>{{ x.due||'未确定' }}</span><div class="progress"><span>{{ x.stage }} · {{ x.progress }}%</span><i><em :style="{width:x.progress+'%'}"></em></i></div><em :class="x.payment">{{ x.payment }}</em><div class="actions"><button @click="openDetail(x)">详情</button><button @click="advance(x)">推进</button><button @click="openEdit(x)">编辑</button><button class="danger" @click="remove(x)">删除</button></div></div></div></section>
  <div class="lower"><section class="card alerts"><h3>异常与待办</h3><p v-for="x in orders.filter(x=>x.exception)" :key="x.id"><i></i><span><b>{{ x.id }}</b>{{ x.exception }}</span><button @click="openDetail(x)">处理</button></p><el-empty v-if="!orders.some(x=>x.exception)" description="暂无异常" :image-size="50"/></section><section class="card alerts"><h3>质量状态</h3><p v-for="x in orders.filter(x=>['WAITING_PHOTOS','PENDING'].includes(x.quality))" :key="x.id"><i class="quality"></i><span><b>{{ x.id }}</b>{{ x.quality==='WAITING_PHOTOS'?'等待质检照片':'等待质检' }}</span><button @click="setQuality(x,'PASSED')">标记通过</button></p></section></div>
  <el-dialog v-model="dialog" :title="editingId?'编辑订单':'新建订单'" width="680px"><el-form label-position="top"><div class="form-grid"><el-form-item label="报价编号"><el-input v-model="form.quote_id"/></el-form-item><el-form-item label="产品"><el-input v-model="form.product"/></el-form-item><el-form-item label="客户"><el-select v-model="form.customer_id" filterable><el-option v-for="x in customerOptions" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="合作工厂"><el-select v-model="form.factory_id" filterable><el-option v-for="x in factoryOptions" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="订单金额"><el-input-number v-model="form.amount" :min="0"/></el-form-item><el-form-item label="币种"><el-select v-model="form.currency"><el-option label="人民币 CNY" value="CNY"/><el-option label="美元 USD" value="USD"/><el-option label="欧元 EUR" value="EUR"/></el-select></el-form-item><el-form-item label="计划交付"><el-date-picker v-model="form.due" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="执行阶段"><el-select v-model="form.stage"><el-option v-for="s in stages" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="收款状态"><el-select v-model="form.payment"><el-option label="定金待收" value="定金待收"/><el-option label="定金已收" value="定金已收"/><el-option label="尾款待收" value="尾款待收"/><el-option label="已收全款" value="已收全款"/></el-select></el-form-item><el-form-item label="质检状态"><el-select v-model="form.quality"><el-option label="待质检" value="PENDING"/><el-option label="等待照片" value="WAITING_PHOTOS"/><el-option label="通过" value="PASSED"/><el-option label="不合格" value="FAILED"/></el-select></el-form-item><el-form-item label="物流信息" class="wide"><el-input v-model="form.logistics"/></el-form-item><el-form-item label="异常说明" class="wide"><el-input v-model="form.exception" type="textarea" :rows="2"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="detailDialog" title="订单执行详情" width="680px"><div v-if="selected" class="detail"><header><div><b>{{ selected.id }}</b><span>{{ selected.customer }} · {{ selected.product }}</span></div><strong>{{ amountText(selected) }}</strong></header><div class="timeline"><div v-for="s in stages" :key="s" :class="{done:stages.indexOf(s)<=stages.indexOf(selected.stage),active:s===selected.stage}"><i></i><span>{{ s }}</span></div></div><dl><div><dt>合作工厂</dt><dd>{{ selected.factory }}</dd></div><div><dt>计划交付</dt><dd>{{ selected.due }}</dd></div><div><dt>收款状态</dt><dd>{{ selected.payment }}</dd></div><div><dt>质检状态</dt><dd>{{ selected.quality }}</dd></div><div><dt>物流信息</dt><dd>{{ selected.logistics||'尚未录入' }}</dd></div><div><dt>异常</dt><dd>{{ selected.exception||'无' }}</dd></div></dl></div><template #footer><el-button @click="detailDialog=false">关闭</el-button><el-button v-if="selected&&selected.quality!=='PASSED'" type="success" @click="selected&&setQuality(selected,'PASSED')">质检通过</el-button><el-button type="primary" @click="selected&&advance(selected)">推进下一阶段</el-button></template></el-dialog>
</div></template>

<style scoped>
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.stats article,.card{background:#fff;border:1px solid #e2eaf2;border-radius:12px;box-shadow:0 5px 18px rgba(23,47,79,.045)}.stats article{padding:17px}.stats span,.stats em{display:block;color:#8593a5;font-size:9px}.stats strong{display:block;font-size:22px;color:#203249;margin:5px 0}.stats strong.danger{color:#df6550}.stats em{font-style:normal;color:#24a47e}.card{padding:18px}.card>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.card h3{margin:0;font-size:15px}.card>header>div{display:flex;gap:8px}.card>header .el-input{width:240px}.card>header .el-select{width:120px}.row{display:grid;grid-template-columns:1.15fr 1.2fr .6fr .6fr 1fr .65fr 1.15fr;gap:12px;align-items:center;min-height:64px;border-top:1px solid #edf1f5;color:#586b80;font-size:9px}.row.head{min-height:34px;border:0;color:#95a0ae}.row b,.row small{display:block}.row small{color:#96a2af;margin-top:3px}.order-id{color:#286fd1}.progress i{display:block;height:6px;background:#edf2f6;border-radius:3px;overflow:hidden;margin-top:6px}.progress i em{display:block;height:100%;background:linear-gradient(90deg,#2f7be2,#22af89)}.row>em{font-style:normal;width:fit-content;padding:4px 7px;border-radius:10px;background:#e8f7f2;color:#168463}.row>em.尾款待收,.row>em.定金待收{background:#fff1dc;color:#c27420}.actions{display:flex;gap:3px}.actions button{border:0;background:#edf4ff;color:#286ed0;border-radius:4px;padding:5px 6px;font-size:8px;cursor:pointer}.actions .danger{background:#fff0ef;color:#d65b4c}.lower{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.alerts h3{margin:0 0 8px}.alerts p{display:grid;grid-template-columns:8px 1fr auto;gap:8px;align-items:center;min-height:44px;border-top:1px solid #edf1f5;font-size:9px;color:#66798e}.alerts p>i{width:7px;height:7px;border-radius:50%;background:#ef8b3e}.alerts p>i.quality{background:#357ee1}.alerts p b{display:block;color:#334a63}.alerts p button{border:0;background:#edf4ff;color:#286fd0;border-radius:5px;padding:5px 8px;cursor:pointer}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .wide{grid-column:1/-1}.form-grid .el-select,.form-grid .el-date-editor,.form-grid .el-input-number{width:100%}.detail>header{display:flex;justify-content:space-between}.detail>header span{display:block;color:#7d8d9f;font-size:10px;margin-top:4px}.detail>header>strong{color:#139473}.timeline{display:flex;justify-content:space-between;margin:28px 0}.timeline>div{position:relative;flex:1;text-align:center;color:#9ba6b3;font-size:8px}.timeline>div:not(:last-child):after{content:'';position:absolute;top:5px;left:55%;width:90%;height:2px;background:#dfe6ee}.timeline i{display:block;width:11px;height:11px;border-radius:50%;background:#dfe6ee;margin:0 auto 7px;position:relative;z-index:1}.timeline .done i,.timeline .done:after{background:#27aa84}.timeline .active i{box-shadow:0 0 0 5px #e3f5ef}.detail dl{border:1px solid #e3eaf1;border-radius:8px;overflow:hidden}.detail dl div{display:grid;grid-template-columns:120px 1fr;border-bottom:1px solid #e8edf3}.detail dl div:last-child{border:0}.detail dt,.detail dd{margin:0;padding:9px;font-size:10px}.detail dt{background:#f7f9fc;color:#77879a}@media(max-width:950px){.stats{grid-template-columns:1fr 1fr}.table{overflow:auto}.row{min-width:950px}.lower{grid-template-columns:1fr}}@media(max-width:600px){.stats,.form-grid{grid-template-columns:1fr}.card>header{align-items:flex-start;flex-direction:column;gap:10px}.card>header>div{flex-wrap:wrap}.card>header .el-input,.card>header .el-select{width:100%}}
</style>
